using System.Text;
using System.Text.Json;
namespace ReplayPanel.Supervisor.BundleTools;

public sealed record UiOptions(string Framework, bool TypeScript, bool Router, bool State, bool Tailwind,string[]? Packages=null,string? StateLibrary=null);
public sealed record NewProject(string Name, string Author, string Description, string PackageVersion, UiOptions? Ui);

/// <summary>
/// Project templates for new bundles. The C# part follows the official replayre/guest-csharp-template (MIT, rePLAY.re);
/// the optional ReUi starters are small Vite projects with curated, pinned package versions.
/// </summary>
public static class BundleTemplates
{
    public static readonly string[] Frameworks = ["svelte", "vue", "react"];

    public static readonly Dictionary<string,string> WebPackages=new() { ["zod"]="4.6.7",["clsx"]="2.1.1",["dayjs"]="1.11.23",["@floating-ui/dom"]="1.8.0",["vitest"]="5.0.4",["prettier"]="3.9.10",["prettier-plugin-svelte"]="4.1.1",["lucide-svelte"]="1.0.1",["lucide-vue-next"]="1.0.0",["lucide-react"]="1.57.0",["@tanstack/svelte-query"]="6.3.2",["@tanstack/vue-query"]="5.104.2",["@tanstack/react-query"]="5.104.2" };

    // Curated JavaScript package versions (verified to build together). They change only with a panel release, never automatically.
    private const string Vite = "8.3.4", TypeScript = "6.0.3", Tailwind = "4.3.3";
    private const string Svelte = "5.57.2", SveltePlugin = "7.3.1", SvelteCheck = "4.7.6", SvelteTsConfig = "5.0.8";
    private const string Vue = "3.5.44", VuePlugin = "6.0.10", VueTsc = "3.3.13", Pinia = "4.0.3", VueRouter = "5.4.0";
    private const string React = "19.3.0", ReactPlugin = "6.1.2", ReactTypes = "19.3.0", Zustand = "5.0.15", ReactRouter = "7.18.4";

    private static string Toml(string value) => value.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", " ").Replace("\n", " ");

    public static Dictionary<string, string> Render(NewProject p)
    {
        var files = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            [".editorconfig"] = "root = true\n\n[*]\nend_of_line = lf\ninsert_final_newline = true\nindent_style = space\nindent_size = 4\n\n[*.{json,js,ts,svelte,vue,jsx,tsx,css,html}]\nindent_size = 2\n\n[*.md]\ntrim_trailing_whitespace = false\n",
            [".gitignore"] = "bin/\nobj/\ndist/\nnode_modules/\nui/dist/\nui/build/\n.vs/\n*.user\n.env\n",
            ["NOTICE.md"] = "# Notice\n\nThe C# project layout (sv/cl/sh, nuget.config, Directory.Build.targets) is derived from the official `replayre/guest-csharp-template`,\nMIT License, Copyright (c) 2026 rePLAY.re. Generated by the BlackICE Server Panel bundle tools (experimental).\n",
            ["README.md"] = $"# {p.Name}\n\n{p.Description}\n\nBuilt and managed with the BlackICE Server Panel (Bundles → Projects). The build result is written into `data/ugc/<name>` of the game server. Do not copy a config.toml into subfolders of that bundle folder: REServer refuses bundles that contain nested manifests.\n\nLocal development: `dotnet build -c Release` creates `dist/` with `config.toml`, `sv.wasm` and `cl.wasm`.\n",
            ["nuget.config"] = NuGetConfig,
            ["Directory.Build.targets"] = BuildTargets(p.Ui is not null),
            ["sh/sh.csproj"] = Csproj("replay.blackice.shared", p.PackageVersion, false, null),
            ["sh/Message.cs"] = "[Msgpack.Gen]\npublic partial record Message(string Text);\n",
            ["sv/sv.csproj"] = Csproj("replay.blackice.server", p.PackageVersion, true, "sh"),
            ["sv/App.cs"] = "public static class App\n{\n    public static void Start()\n    {\n        Console.WriteLine(\"Hello world!\");\n\n        re.Events.OnNet<Message>(\n            \"ping\",\n            (clientId, x) =>\n            {\n                re.Events.EmitNetTargeted(\"pong\", clientId, x);\n            }\n        );\n    }\n}\n",
            ["cl/cl.csproj"] = Csproj("replay.blackice.client", p.PackageVersion, true, "sh"),
            ["cl/App.cs"] = "public static class App\n{\n    public static void Start()\n    {\n        Console.WriteLine(\"Hello world!\");\n\n        re.Con.RegisterCommand(\n            \"ping\",\n            x =>\n            {\n                re.Events.EmitNet(\"ping\", new Message(x.FirstOrDefault() ?? \"\"));\n            }\n        );\n\n        re.Events.OnNet<Message>(\n            \"pong\",\n            x =>\n            {\n                Console.WriteLine($\"Event received: {x.Text}\");\n            }\n        );\n    }\n}\n",
            ["data/config.toml"] = Manifest(p),
            ["vfs/.gitkeep"] = "",
        };
        if(p.Ui?.Packages is {} extra&&extra.Any(x=>!WebPackages.ContainsKey(x)&&x is not ("icons" or "query")))throw new InvalidOperationException("bundleTools.package");
        if (p.Ui is not null) foreach (var (path, content) in UiFiles(p, p.Ui)) files["ui/" + path] = content;
        return files;
    }

    private const string NuGetConfig = """
        <?xml version="1.0" encoding="utf-8"?>
        <configuration>
          <packageSources>
            <clear />
            <add key="nuget.org" value="https://api.nuget.org/v3/index.json" />
            <add key="dotnet-experimental" value="https://pkgs.dev.azure.com/dnceng/public/_packaging/dotnet-experimental/nuget/v3/index.json" />
          </packageSources>
          <packageSourceMapping>
            <packageSource key="dotnet-experimental">
              <package pattern="Microsoft.DotNet.ILCompiler.LLVM" />
              <package pattern="runtime.*.Microsoft.DotNet.ILCompiler.LLVM" />
            </packageSource>
            <packageSource key="nuget.org">
              <package pattern="*" />
            </packageSource>
          </packageSourceMapping>
        </configuration>
        """ + "\n";

    /// <summary>The panel restores packages with this fixed file so a repository cannot add its own package feeds.</summary>
    public static string PanelNuGetConfig => NuGetConfig;

    private static string BuildTargets(bool ui) => """
        <Project>
          <PropertyGroup>
            <DistDir>$(MSBuildThisFileDirectory)dist/</DistDir>
          </PropertyGroup>

          <!-- Optional local staging: copies the manifest and both blobs into dist/ after every build. -->
          <Target Name="CopyWasiArtifacts" AfterTargets="Build">
            <MakeDir Directories="$(DistDir)" />
            <Copy SourceFiles="$(MSBuildThisFileDirectory)data/config.toml" DestinationFolder="$(DistDir)" SkipUnchangedFiles="true" Condition="Exists('$(MSBuildThisFileDirectory)data/config.toml')" />
            <Copy SourceFiles="$(MSBuildThisFileDirectory)cl/bin/$(Configuration)/net10.0/wasi-wasm/native/cl.wasm" DestinationFolder="$(DistDir)" Condition="Exists('$(MSBuildThisFileDirectory)cl/bin/$(Configuration)/net10.0/wasi-wasm/native/cl.wasm')" />
            <Copy SourceFiles="$(MSBuildThisFileDirectory)sv/bin/$(Configuration)/net10.0/wasi-wasm/native/sv.wasm" DestinationFolder="$(DistDir)" Condition="Exists('$(MSBuildThisFileDirectory)sv/bin/$(Configuration)/net10.0/wasi-wasm/native/sv.wasm')" />
          </Target>
        </Project>
        """ + "\n";

    private static string Csproj(string package, string version, bool wasm, string? reference)
    {
        var sb = new StringBuilder();
        sb.Append("<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <OutputType>Library</OutputType>\n    <RuntimeIdentifier>wasi-wasm</RuntimeIdentifier>\n    <TargetFramework>net10.0</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>enable</Nullable>\n    <PublishTrimmed>true</PublishTrimmed>\n    <SelfContained>true</SelfContained>\n    <InvariantGlobalization>true</InvariantGlobalization>\n    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>\n");
        if (wasm) sb.Append("    <MSBuildEnableWorkloadResolver>false</MSBuildEnableWorkloadResolver>\n    <EmitCompilerGeneratedFiles>true</EmitCompilerGeneratedFiles>\n");
        else sb.Append("    <UseAppHost>false</UseAppHost>\n");
        sb.Append("  </PropertyGroup>\n\n  <ItemGroup>\n    <PackageReference Include=\"").Append(package).Append("\" Version=\"").Append(version).Append("\" />\n");
        if (!wasm) sb.Append("    <PackageReference Include=\"Serde\" Version=\"0.10.2\" />\n");
        sb.Append("  </ItemGroup>\n");
        if (reference is not null) sb.Append("\n  <ItemGroup>\n    <ProjectReference Include=\"../").Append(reference).Append('/').Append(reference).Append(".csproj\" />\n  </ItemGroup>\n");
        sb.Append("</Project>\n");
        return sb.ToString();
    }

    private static string Manifest(NewProject p)
    {
        var sb = new StringBuilder();
        sb.Append("[General]\ndescription = \"").Append(Toml(p.Description)).Append("\"\nauthor = \"").Append(Toml(p.Author)).Append("\"\nversion = \"0.1.0\"\n\n");
        sb.Append("[Scripting]\nclient_blob = \"cl.wasm\"\nserver_blob = \"sv.wasm\"\n\n");
        if (p.Ui is null) sb.Append("[ReUi]\n\n");
        else sb.Append("[ReUi]\ninitial_page = \"index.html\"\ncontent_root = \"ui/\"\nfiles = [\"ui/**\"]\n\n");
        sb.Append("[Meta]\nconfig_version = \"alpha_playtest\"\n");
        return sb.ToString();
    }

    // ------------------------------------------------------------------ ReUi starters (paths relative to ui/)
    private static Dictionary<string, string> UiFiles(NewProject p, UiOptions ui)
    {
        StateTemplates.Validate(ui);
        if(ui.StateLibrary is not null)ui=ui with{State=ui.StateLibrary!="none"};
        var ts = ui.TypeScript;
        var ext = ts ? "ts" : "js";
        var files = new Dictionary<string, string>(StringComparer.Ordinal);
        var deps = new SortedDictionary<string, string>(StringComparer.Ordinal);
        var dev = new SortedDictionary<string, string>(StringComparer.Ordinal) { ["vite"] = Vite };
        if (ts) dev["typescript"] = TypeScript;
        var scripts = new SortedDictionary<string, string>(StringComparer.Ordinal) { ["dev"] = "vite", ["build"] = "vite build", ["preview"] = "vite preview" };
        string plugins = "", imports = "", main;
        var css = "body { margin: 0; font-family: system-ui, sans-serif; color: #f5d8d9; background: transparent; }\n#app { padding: 16px; }\n.panel { display: inline-block; padding: 12px 16px; border: 1px solid #834653; background: rgba(16,17,22,.85); }\nbutton { cursor: pointer; }\n";
        if (ui.Tailwind) { dev["tailwindcss"] = Tailwind; dev["@tailwindcss/vite"] = Tailwind; imports += "import tailwindcss from '@tailwindcss/vite'\n"; plugins += ", tailwindcss()"; css = "@import \"tailwindcss\";\n\n" + css; }
        var tail = ui.Tailwind ? "class=\"panel text-sm\"" : "class=\"panel\"";
        var title = p.Name;

        switch (ui.Framework)
        {
            case "svelte":
                deps["svelte"] = Svelte; dev["@sveltejs/vite-plugin-svelte"] = SveltePlugin;
                imports = "import { svelte } from '@sveltejs/vite-plugin-svelte'\n" + imports; plugins = "svelte()" + plugins;
                if (ts) { dev["svelte-check"] = SvelteCheck; dev["@tsconfig/svelte"] = SvelteTsConfig; scripts["check"] = "svelte-check --tsconfig ./tsconfig.json"; files["tsconfig.json"] = "{\n  \"extends\": \"@tsconfig/svelte/tsconfig.json\",\n  \"compilerOptions\": { \"target\": \"ESNext\", \"module\": \"ESNext\", \"moduleResolution\": \"bundler\", \"strict\": true, \"types\": [\"svelte\", \"vite/client\"] },\n  \"include\": [\"src/**/*.ts\", \"src/**/*.svelte\"]\n}\n"; }
                files["svelte.config.js"] = "import { vitePreprocess } from '@sveltejs/vite-plugin-svelte'\n\nexport default { preprocess: vitePreprocess() }\n";
                main = "import { mount } from 'svelte'\nimport './app.css'\nimport App from './App.svelte'\n\nexport default mount(App, { target: document.getElementById('app')" + (ts ? "!" : "") + " })\n";
                var storeImport = ui.State ? "  import { counter } from './store.svelte'\n" : "";
                if (ui.State) files["src/store.svelte." + ext] = "export const counter = $state({ value: 0 })\n";
                var count = ui.State ? "counter.value" : "count";
                files["src/App.svelte"] = $"<script{(ts ? " lang=\"ts\"" : "")}>\n{storeImport}{(ui.State ? "" : "  let count = $state(0)\n")}  let status = $state('waiting for the game client')\n\n  window.addEventListener('message', (event) => {{\n    try {{\n      const {{ messageName, payload }} = JSON.parse(event.data)\n      status = `${{messageName}}: ${{JSON.stringify(payload)}}`\n    }} catch {{\n      /* ignore messages that are not JSON */\n    }}\n  }})\n\n  async function ping() {{\n    await fetch('https://ugc-message/{Slug(title)}-ping', {{ method: 'POST', body: JSON.stringify({{ value: {count} }}) }})\n  }}\n</script>\n\n<main {tail}>\n  <h1>{Html(title)}</h1>\n  <p>{{status}}</p>\n  <button onclick={{() => {count}++}}>Clicked {{{count}}} times</button>\n  <button onclick={{ping}}>Send to client</button>\n</main>\n";
                break;
            case "vue":
                deps["vue"] = Vue; dev["@vitejs/plugin-vue"] = VuePlugin;
                imports = "import vue from '@vitejs/plugin-vue'\n" + imports; plugins = "vue()" + plugins;
                if (ts) { dev["vue-tsc"] = VueTsc; scripts["check"] = "vue-tsc --noEmit"; files["tsconfig.json"] = "{\n  \"compilerOptions\": { \"target\": \"ESNext\", \"module\": \"ESNext\", \"moduleResolution\": \"bundler\", \"strict\": true, \"jsx\": \"preserve\", \"types\": [\"vite/client\"], \"noEmit\": true },\n  \"include\": [\"src/**/*.ts\", \"src/**/*.vue\"]\n}\n"; files["src/env.d.ts"] = "declare module '*.vue' {\n  import type { DefineComponent } from 'vue'\n  const component: DefineComponent<object, object, unknown>\n  export default component\n}\n"; }
                var useStore = ui.State; var useRouter = ui.Router;
                if (useStore) { deps["pinia"] = Pinia; files["src/stores/counter." + ext] = "import { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nexport const useCounter = defineStore('counter', () => {\n  const value = ref(0)\n  return { value }\n})\n"; }
                if (useRouter) { deps["vue-router"] = VueRouter; files["src/router." + ext] = "import { createRouter, createWebHashHistory } from 'vue-router'\nimport Home from './views/Home.vue'\nimport About from './views/About.vue'\n\n// Hash history keeps routing independent of the file path the game serves the page from.\nexport default createRouter({\n  history: createWebHashHistory(),\n  routes: [\n    { path: '/', component: Home },\n    { path: '/about', component: About },\n  ],\n})\n"; files["src/views/About.vue"] = "<template><p>About this bundle UI.</p></template>\n"; }
                main = "import { createApp } from 'vue'\n" + (useStore ? "import { createPinia } from 'pinia'\n" : "") + (useRouter ? "import router from './router'\n" : "") + "import './app.css'\nimport App from './App.vue'\n\ncreateApp(App)" + (useStore ? ".use(createPinia())" : "") + (useRouter ? ".use(router)" : "") + ".mount('#app')\n";
                var view = $"<script setup{(ts ? " lang=\"ts\"" : "")}>\nimport {{ ref }} from 'vue'\n{(useStore ? (useRouter ? "import { useCounter } from '../stores/counter'\n" : "import { useCounter } from './stores/counter'\n") : "")}\n{(useStore ? "const counter = useCounter()\n" : "const count = ref(0)\n")}const status = ref('waiting for the game client')\n\nwindow.addEventListener('message', (event) => {{\n  try {{\n    const {{ messageName, payload }} = JSON.parse(event.data)\n    status.value = `${{messageName}}: ${{JSON.stringify(payload)}}`\n  }} catch {{\n    // ignore messages that are not JSON\n  }}\n}})\n\nasync function ping() {{\n  await fetch('https://ugc-message/{Slug(title)}-ping', {{ method: 'POST', body: JSON.stringify({{ value: {(useStore ? "counter.value" : "count.value")} }}) }})\n}}\n</script>\n\n<template>\n  <main {tail}>\n    <h1>{Html(title)}</h1>\n    <p>{{{{ status }}}}</p>\n    <button @click=\"{(useStore ? "counter.value++" : "count++")}\">Clicked {{{{ {(useStore ? "counter.value" : "count")} }}}} times</button>\n    <button @click=\"ping\">Send to client</button>\n  </main>\n</template>\n";
                if (useRouter) { files["src/views/Home.vue"] = view; files["src/App.vue"] = "<template>\n  <nav><router-link to=\"/\">Home</router-link> · <router-link to=\"/about\">About</router-link></nav>\n  <router-view />\n</template>\n"; }
                else files["src/App.vue"] = view;
                break;
            default: // react
                deps["react"] = React; deps["react-dom"] = React; dev["@vitejs/plugin-react"] = ReactPlugin;
                imports = "import react from '@vitejs/plugin-react'\n" + imports; plugins = "react()" + plugins;
                var jsx = ts ? "tsx" : "jsx";
                if (ts) { dev["@types/react"] = ReactTypes; dev["@types/react-dom"] = ReactTypes; scripts["check"] = "tsc --noEmit"; files["tsconfig.json"] = "{\n  \"compilerOptions\": { \"target\": \"ESNext\", \"module\": \"ESNext\", \"moduleResolution\": \"bundler\", \"strict\": true, \"jsx\": \"react-jsx\", \"types\": [\"vite/client\"], \"noEmit\": true, \"skipLibCheck\": true },\n  \"include\": [\"src\"]\n}\n"; }
                if (ui.State) { deps["zustand"] = Zustand; files["src/store." + ext] = ts ? "import { create } from 'zustand'\n\ninterface CounterState {\n  value: number\n  increment: () => void\n}\n\nexport const useCounter = create<CounterState>((set) => ({\n  value: 0,\n  increment: () => set((state) => ({ value: state.value + 1 })),\n}))\n" : "import { create } from 'zustand'\n\nexport const useCounter = create((set) => ({\n  value: 0,\n  increment: () => set((state) => ({ value: state.value + 1 })),\n}))\n"; }
                if (ui.Router) deps["react-router-dom"] = ReactRouter;
                main = "import { createRoot } from 'react-dom/client'\n" + (ui.Router ? "import { HashRouter } from 'react-router-dom'\n" : "") + "import './app.css'\nimport App from './App'\n\ncreateRoot(document.getElementById('app')" + (ts ? "!" : "") + ").render(" + (ui.Router ? "<HashRouter><App /></HashRouter>" : "<App />") + ")\n";
                var counterHook = ui.State ? "  const { value, increment } = useCounter()\n" : "  const [value, setValue] = useState(0)\n  const increment = () => setValue(value + 1)\n";
                files["src/App." + jsx] = $"import {{ useEffect, useState }} from 'react'\n{(ui.Router ? "import { Link, Route, Routes } from 'react-router-dom'\n" : "")}{(ui.State ? "import { useCounter } from './store'\n" : "")}\nfunction Home() {{\n{counterHook}  const [status, setStatus] = useState('waiting for the game client')\n\n  useEffect(() => {{\n    const listener = (event{(ts ? ": MessageEvent" : "")}) => {{\n      try {{\n        const {{ messageName, payload }} = JSON.parse(event.data)\n        setStatus(`${{messageName}}: ${{JSON.stringify(payload)}}`)\n      }} catch {{\n        // ignore messages that are not JSON\n      }}\n    }}\n    window.addEventListener('message', listener)\n    return () => window.removeEventListener('message', listener)\n  }}, [])\n\n  const ping = () => fetch('https://ugc-message/{Slug(title)}-ping', {{ method: 'POST', body: JSON.stringify({{ value }}) }})\n\n  return (\n    <main {tail.Replace("class=", "className=")}>\n      <h1>{Html(title)}</h1>\n      <p>{{status}}</p>\n      <button onClick={{increment}}>Clicked {{value}} times</button>\n      <button onClick={{ping}}>Send to client</button>\n    </main>\n  )\n}}\n\nexport default function App() {{\n  return (\n{(ui.Router ? "    <>\n      <nav><Link to=\"/\">Home</Link> · <Link to=\"/about\">About</Link></nav>\n      <Routes>\n        <Route path=\"/\" element={<Home />} />\n        <Route path=\"/about\" element={<p>About this bundle UI.</p>} />\n      </Routes>\n    </>\n" : "    <Home />\n")}  )\n}}\n";
                break;
        }
        var entry = ui.Framework == "react" ? (ts ? "tsx" : "jsx") : ext;
        files["index.html"] = $"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>{Html(title)}</title>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"/src/main.{entry}\"></script>\n  </body>\n</html>\n";
        files["src/main." + entry] = main;
        StateTemplates.Apply(ui,files,deps);
        files["src/app.css"] = css;
        files["vite.config." + ext] = $"import {{ defineConfig }} from 'vite'\n{imports}\n// Relative asset paths: the game serves this UI from the bundle folder, not from a web root.\nexport default defineConfig({{\n  base: './',\n  plugins: [{plugins}],\n  build: {{ outDir: 'dist', emptyOutDir: true }},\n}})\n";
        foreach(var option in ui.Packages??[]){var package=option=="icons"?(ui.Framework=="vue"?"lucide-vue-next":ui.Framework=="react"?"lucide-react":"lucide-svelte"):option=="query"?"@tanstack/"+ui.Framework+"-query":option;if(!WebPackages.TryGetValue(package,out var version))throw new InvalidOperationException("bundleTools.package");if(package is "vitest" or "prettier")dev[package]=version;else deps[package]=version;}
        if((ui.Packages??[]).Contains("vitest"))scripts["test"]="vitest run --passWithNoTests";
        if((ui.Packages??[]).Contains("prettier")){scripts["format"]="prettier --write src";if(ui.Framework=="svelte"){dev["prettier-plugin-svelte"]=WebPackages["prettier-plugin-svelte"];files[".prettierrc.json"]="{\"plugins\":[\"prettier-plugin-svelte\"]}\n";}}
        files["package.json"] = JsonSerializer.Serialize(new Dictionary<string, object> { ["name"] = Slug(title) + "-ui", ["private"] = true, ["version"] = "0.1.0", ["type"] = "module", ["scripts"] = scripts, ["dependencies"] = deps, ["devDependencies"] = dev }, new JsonSerializerOptions { WriteIndented = true }) + "\n";
        files[".gitignore"] = "node_modules/\ndist/\n";
        return files;
    }

    public static string Slug(string value)
    {
        var slug = new string(value.ToLowerInvariant().Select(c => char.IsAsciiLetterOrDigit(c) ? c : '-').ToArray()).Trim('-');
        return slug.Length == 0 ? "bundle" : slug;
    }

    private static string Html(string value) => System.Net.WebUtility.HtmlEncode(value);
}
